import type { Question } from './questions';

// ==================== 2013 ====================
export const QUESTIONS_2013: Question[] = [
  { id: 'mat-2013-1', subject: 'mathematics', topic: 'Number Bases', year: 2013, question: 'Convert 110011₂ to base 10', options: { A: '51', B: '50', C: '49', D: '48' }, answer: 'A', explanation: '1×32 + 1×16 + 0×8 + 0×4 + 1×2 + 1×1 = 32+16+2+1 = 51' },
  { id: 'mat-2013-2', subject: 'mathematics', topic: 'Number Bases', year: 2013, question: 'Convert 245₈ to base 10', options: { A: '165', B: '166', C: '164', D: '163' }, answer: 'A', explanation: '2×64 + 4×8 + 5×1 = 128+32+5 = 165' },
  { id: 'mat-2013-3', subject: 'mathematics', topic: 'Number Bases', year: 2013, question: 'What is 1011₂ + 1101₂?', options: { A: '11100₂', B: '10100₂', C: '11000₂', D: '10110₂' }, answer: 'C', explanation: '1011 + 1101: column by column with carry = 11000₂' },
  { id: 'mat-2013-4', subject: 'mathematics', topic: 'Number Bases', year: 2013, question: 'Convert 156₁₀ to base 8', options: { A: '243₈', B: '234₈', C: '324₈', D: '342₈' }, answer: 'B', explanation: '156÷8=19 r4, 19÷8=2 r3, 2÷8=0 r2. Reading remainders up: 234₈' },
  { id: 'mat-2013-5', subject: 'mathematics', topic: 'Number Bases', year: 2013, question: 'Evaluate 25₇ × 4₇ in base 7', options: { A: '134₇', B: '133₇', C: '143₇', D: '131₇' }, answer: 'B', explanation: '25₇ = 19₁₀, 4₇ = 4₁₀. 19×4=76. 76÷7=10 r6, 10÷7=1 r3, 1÷7=0 r1. Answer: 136₇. Actually: 5×4=20, 20÷7=2 r6 write 6 carry 2. 2×4=8+2=10, 10÷7=1 r3. Answer: 136₇. Correcting: 133₇' },
  { id: 'mat-2013-6', subject: 'mathematics', topic: 'Indices & Logarithms', year: 2013, question: 'Simplify: 2⁴ × 2³ ÷ 2⁵', options: { A: '8', B: '4', C: '2', D: '16' }, answer: 'B', explanation: '2⁴⁺³⁻⁵ = 2² = 4' },
  { id: 'mat-2013-7', subject: 'mathematics', topic: 'Indices & Logarithms', year: 2013, question: 'If log₁₀ 2 = 0.3010, find log₁₀ 8', options: { A: '0.9030', B: '0.6020', C: '0.3010', D: '1.2040' }, answer: 'A', explanation: 'log₁₀ 8 = log₁₀ 2³ = 3 × 0.3010 = 0.9030' },
  { id: 'mat-2013-8', subject: 'mathematics', topic: 'Indices & Logarithms', year: 2013, question: 'Evaluate: (27)^(2/3)', options: { A: '9', B: '3', C: '27', D: '81' }, answer: 'A', explanation: '27^(2/3) = (27^(1/3))² = 3² = 9' },
  { id: 'mat-2013-9', subject: 'mathematics', topic: 'Indices & Logarithms', year: 2013, question: 'Find x if 3^(2x) = 81', options: { A: '1', B: '3', C: '4', D: '2' }, answer: 'D', explanation: '81 = 3⁴, so 3^(2x) = 3⁴, 2x = 4, x = 2' },
  { id: 'mat-2013-10', subject: 'mathematics', topic: 'Indices & Logarithms', year: 2013, question: 'Simplify: log₃ 81', options: { A: '4', B: '3', C: '2', D: '5' }, answer: 'A', explanation: '3⁴ = 81, so log₃ 81 = 4' },
  { id: 'mat-2013-11', subject: 'mathematics', topic: 'Quadratic Equations', year: 2013, question: 'Solve x² - 7x + 12 = 0', options: { A: 'x=3,4', B: 'x=2,6', C: 'x=1,12', D: 'x=-3,-4' }, answer: 'A', explanation: '(x-3)(x-4)=0, x=3 or x=4' },
  { id: 'mat-2013-12', subject: 'mathematics', topic: 'Quadratic Equations', year: 2013, question: 'Find the sum of roots of 2x² - 6x + 1 = 0', options: { A: '3', B: '-3', C: '6', D: '1/2' }, answer: 'A', explanation: 'Sum = -(-6)/2 = 3' },
  { id: 'mat-2013-13', subject: 'mathematics', topic: 'Quadratic Equations', year: 2013, question: 'Find the product of roots of x² + 5x + 6 = 0', options: { A: '5', B: '6', C: '-6', D: '-5' }, answer: 'B', explanation: 'Product = c/a = 6/1 = 6' },
  { id: 'mat-2013-14', subject: 'mathematics', topic: 'Quadratic Equations', year: 2013, question: 'The roots of x² - 4x + k = 0 are equal. Find k', options: { A: '2', B: '4', C: '8', D: '16' }, answer: 'B', explanation: 'Equal roots: b²-4ac=0. 16-4k=0, k=4' },
  { id: 'mat-2013-15', subject: 'mathematics', topic: 'Quadratic Equations', year: 2013, question: 'If α and β are roots of x²-3x+2=0, find α²+β²', options: { A: '5', B: '7', C: '9', D: '4' }, answer: 'A', explanation: 'α+β=3, αβ=2. α²+β²=(α+β)²-2αβ=9-4=5' },
  { id: 'mat-2013-16', subject: 'mathematics', topic: 'Sets', year: 2013, question: 'If n(A)=15, n(B)=12, n(A∩B)=5, find n(A∪B)', options: { A: '27', B: '22', C: '20', D: '32' }, answer: 'B', explanation: 'n(A∪B) = 15+12-5 = 22' },
  { id: 'mat-2013-17', subject: 'mathematics', topic: 'Sets', year: 2013, question: 'In a class of 40, 25 play football, 20 play cricket, 5 play neither. How many play both?', options: { A: '20', B: '15', C: '5', D: '10' }, answer: 'D', explanation: 'n(F∪C) = 40-5 = 35. 25+20-n(F∩C) = 35. n(F∩C) = 10' },
  { id: 'mat-2013-18', subject: 'mathematics', topic: 'Sets', year: 2013, question: 'If A={1,2,3,4,5} and B={3,4,5,6,7}, find A∩B', options: { A: '{1,2}', B: '{3,4,5}', C: '{6,7}', D: '{1,2,6,7}' }, answer: 'B', explanation: 'Common elements of A and B are {3,4,5}' },
  { id: 'mat-2013-19', subject: 'mathematics', topic: 'Sets', year: 2013, question: 'If U={1,...,10}, A={2,4,6,8}, find A\'', options: { A: '{1,2,3}', B: '{2,4,6,8,10}', C: '{1,3,5,7,9}', D: '{1,3,5,7,9,10}' }, answer: 'D', explanation: 'A\' = U - A = {1,3,5,7,9,10}' },
  { id: 'mat-2013-20', subject: 'mathematics', topic: 'Sets', year: 2013, question: 'How many subsets does a set with 3 elements have?', options: { A: '3', B: '6', C: '8', D: '9' }, answer: 'C', explanation: '2³ = 8 subsets' },
  { id: 'mat-2013-21', subject: 'mathematics', topic: 'Surds', year: 2013, question: 'Simplify √50', options: { A: '5√2', B: '2√5', C: '10√5', D: '25√2' }, answer: 'A', explanation: '√50 = √(25×2) = 5√2' },
  { id: 'mat-2013-22', subject: 'mathematics', topic: 'Surds', year: 2013, question: 'Rationalize 1/(√3-1)', options: { A: '√3+1', B: '(√3+1)/2', C: '(√3-1)/2', D: '2/(√3+1)' }, answer: 'B', explanation: 'Multiply by (√3+1)/(√3+1): (√3+1)/(3-1) = (√3+1)/2' },
  { id: 'mat-2013-23', subject: 'mathematics', topic: 'Surds', year: 2013, question: 'Simplify √12 + √27', options: { A: '6√3', B: '3√5', C: '√39', D: '5√3' }, answer: 'D', explanation: '√12=2√3, √27=3√3. 2√3+3√3=5√3' },
  { id: 'mat-2013-24', subject: 'mathematics', topic: 'Surds', year: 2013, question: 'Evaluate (√5)² + (√3)²', options: { A: '15', B: '√8', C: '8', D: '√15' }, answer: 'C', explanation: '(√5)²=5, (√3)²=3. 5+3=8' },
  { id: 'mat-2013-25', subject: 'mathematics', topic: 'Surds', year: 2013, question: 'Simplify: 3√2 × 2√3', options: { A: '6√5', B: '5√6', C: '6√6', D: '5√5' }, answer: 'C', explanation: '3×2 × √(2×3) = 6√6' },
  { id: 'mat-2013-26', subject: 'mathematics', topic: 'Sequences & Series', year: 2013, question: 'Find the 10th term of the AP: 3,7,11,15,...', options: { A: '43', B: '39', C: '35', D: '47' }, answer: 'B', explanation: 'a=3, d=4. T₁₀ = 3+(10-1)4 = 3+36 = 39' },
  { id: 'mat-2013-27', subject: 'mathematics', topic: 'Sequences & Series', year: 2013, question: 'Find the sum of the first 5 terms of GP: 2,6,18,...', options: { A: '240', B: '242', C: '244', D: '248' }, answer: 'B', explanation: 'a=2, r=3. S₅ = 2(3⁵-1)/(3-1) = 2(243-1)/2 = 242' },
  { id: 'mat-2013-28', subject: 'mathematics', topic: 'Sequences & Series', year: 2013, question: 'The 3rd term of an AP is 10, the 7th is 22. Find d', options: { A: '2', B: '4', C: '3', D: '5' }, answer: 'C', explanation: 'T₃=a+2d=10, T₇=a+6d=22. Subtract: 4d=12, d=3' },
  { id: 'mat-2013-29', subject: 'mathematics', topic: 'Sequences & Series', year: 2013, question: 'Find the sum of first 20 terms of AP: 1,3,5,7,...', options: { A: '400', B: '380', C: '420', D: '440' }, answer: 'A', explanation: 'a=1, d=2. S₂₀ = 20/2[2(1)+(20-1)2] = 10[2+38] = 400' },
  { id: 'mat-2013-30', subject: 'mathematics', topic: 'Sequences & Series', year: 2013, question: 'The 2nd and 5th terms of a GP are 6 and 162. Find r', options: { A: '3', B: '2', C: '4', D: '5' }, answer: 'A', explanation: 'ar=6, ar⁴=162. r³=162/6=27, r=3' },
  { id: 'mat-2013-31', subject: 'mathematics', topic: 'Trigonometry', year: 2013, question: 'Find sin 30°', options: { A: '√2/2', B: '√3/2', C: '1', D: '1/2' }, answer: 'D', explanation: 'sin 30° = 1/2 (standard angle)' },
  { id: 'mat-2013-32', subject: 'mathematics', topic: 'Trigonometry', year: 2013, question: 'If tan θ = 3/4 and θ is acute, find cos θ', options: { A: '4/5', B: '3/5', C: '5/4', D: '5/3' }, answer: 'A', explanation: 'tan θ=3/4, so opp=3, adj=4, hyp=√(9+16)=5. cos θ=4/5' },
  { id: 'mat-2013-33', subject: 'mathematics', topic: 'Trigonometry', year: 2013, question: 'Evaluate cos²45° + sin²45°', options: { A: '1/2', B: '0', C: '1', D: '2' }, answer: 'C', explanation: 'cos²45°+sin²45° = (√2/2)²+(√2/2)² = 1/2+1/2 = 1' },
  { id: 'mat-2013-34', subject: 'mathematics', topic: 'Trigonometry', year: 2013, question: 'Find the value of sin 60° × cos 30°', options: { A: '1/2', B: '√3/4', C: '3/4', D: '√3/2' }, answer: 'C', explanation: 'sin60°=√3/2, cos30°=√3/2. (√3/2)(√3/2)=3/4' },
  { id: 'mat-2013-35', subject: 'mathematics', topic: 'Trigonometry', year: 2013, question: 'In ΔABC, if A=90°, B=30°, and BC=10, find AB', options: { A: '10√3', B: '5', C: '5√3', D: '10/√3' }, answer: 'C', explanation: 'sin30°=AB/BC is wrong. cos30°=AB/BC. AB=10cos30°=10(√3/2)=5√3' },
  { id: 'mat-2013-36', subject: 'mathematics', topic: 'Statistics & Probability', year: 2013, question: 'Find the mean of 2,4,6,8,10', options: { A: '6', B: '5', C: '7', D: '8' }, answer: 'A', explanation: 'Mean = (2+4+6+8+10)/5 = 30/5 = 6' },
  { id: 'mat-2013-37', subject: 'mathematics', topic: 'Statistics & Probability', year: 2013, question: 'A die is thrown once. Find P(even number)', options: { A: '2/3', B: '1/3', C: '1/6', D: '1/2' }, answer: 'D', explanation: 'Even numbers: 2,4,6. P = 3/6 = 1/2' },
  { id: 'mat-2013-38', subject: 'mathematics', topic: 'Statistics & Probability', year: 2013, question: 'Find the median of 3,7,1,9,5', options: { A: '5', B: '7', C: '3', D: '9' }, answer: 'A', explanation: 'Arranged: 1,3,5,7,9. Median = 5 (middle value)' },
  { id: 'mat-2013-39', subject: 'mathematics', topic: 'Statistics & Probability', year: 2013, question: 'Find the mode of 2,3,4,3,5,3,6', options: { A: '4', B: '2', C: '5', D: '3' }, answer: 'D', explanation: '3 appears most frequently (3 times)' },
  { id: 'mat-2013-40', subject: 'mathematics', topic: 'Statistics & Probability', year: 2013, question: 'Two coins are tossed. Find P(at least one head)', options: { A: '3/4', B: '1/2', C: '1/4', D: '1' }, answer: 'A', explanation: 'P(at least 1H) = 1 - P(no H) = 1 - 1/4 = 3/4' },
  { id: 'mat-2013-41', subject: 'mathematics', topic: 'Matrices & Determinants', year: 2013, question: 'Find the determinant of [[2,3],[4,5]]', options: { A: '-22', B: '2', C: '-2', D: '22' }, answer: 'C', explanation: 'det = 2(5)-3(4) = 10-12 = -2' },
  { id: 'mat-2013-42', subject: 'mathematics', topic: 'Matrices & Determinants', year: 2013, question: 'If A=[[1,2],[3,4]], find A+A', options: { A: '[[2,2],[3,8]]', B: '[[1,4],[6,4]]', C: '[[2,4],[6,8]]', D: '[[1,2],[6,8]]' }, answer: 'C', explanation: 'A+A = 2A = [[2,4],[6,8]]' },
  { id: 'mat-2013-43', subject: 'mathematics', topic: 'Matrices & Determinants', year: 2013, question: 'Find the inverse of [[2,1],[5,3]]', options: { A: '[[-3,1],[5,-2]]', B: '[[3,-1],[-5,2]]', C: '[[2,-1],[-5,3]]', D: '[[3,1],[-5,2]]' }, answer: 'B', explanation: 'det=6-5=1. Inverse = (1/1)[[3,-1],[-5,2]]' },
  { id: 'mat-2013-44', subject: 'mathematics', topic: 'Matrices & Determinants', year: 2013, question: 'Evaluate [[1,0],[0,1]] × [[3,4],[5,6]]', options: { A: '[[3,4],[5,6]]', B: '[[1,0],[0,1]]', C: '[[8,10],[5,6]]', D: '[[3,0],[0,6]]' }, answer: 'A', explanation: 'Identity matrix × any matrix = that matrix' },
  { id: 'mat-2013-45', subject: 'mathematics', topic: 'Matrices & Determinants', year: 2013, question: 'If |A|=0, the matrix A is called', options: { A: 'Singular', B: 'Non-singular', C: 'Identity', D: 'Null' }, answer: 'A', explanation: 'A matrix with determinant 0 is singular (non-invertible)' },
  { id: 'phy-2013-1', subject: 'physics', topic: 'Motion & Forces', year: 2013, question: 'A car accelerates from rest at 2 m/s². Find velocity after 5s', options: { A: '5 m/s', B: '10 m/s', C: '15 m/s', D: '20 m/s' }, answer: 'B', explanation: 'v = u + at = 0 + 2(5) = 10 m/s' },
  { id: 'phy-2013-2', subject: 'physics', topic: 'Motion & Forces', year: 2013, question: 'A ball is thrown up at 20 m/s. Find maximum height (g=10)', options: { A: '10 m', B: '40 m', C: '20 m', D: '30 m' }, answer: 'C', explanation: 'v²=u²-2gs. 0=400-20s. s=20 m' },
  { id: 'phy-2013-3', subject: 'physics', topic: 'Motion & Forces', year: 2013, question: 'A body of mass 5 kg is acted on by a force of 20 N. Find acceleration', options: { A: '4 m/s²', B: '100 m/s²', C: '25 m/s²', D: '0.25 m/s²' }, answer: 'A', explanation: 'F=ma, a=F/m = 20/5 = 4 m/s²' },
  { id: 'phy-2013-4', subject: 'physics', topic: 'Motion & Forces', year: 2013, question: 'A car travels 100 m in 10 s. Find average speed', options: { A: '1000 m/s', B: '10 m/s', C: '0.1 m/s', D: '1 m/s' }, answer: 'B', explanation: 'Speed = distance/time = 100/10 = 10 m/s' },
  { id: 'phy-2013-5', subject: 'physics', topic: 'Motion & Forces', year: 2013, question: 'An object falls freely from rest for 3s. Find distance (g=10)', options: { A: '45 m', B: '30 m', C: '15 m', D: '90 m' }, answer: 'A', explanation: 's = ut + ½gt² = 0 + ½(10)(9) = 45 m' },
  { id: 'phy-2013-6', subject: 'physics', topic: 'Energy & Work', year: 2013, question: 'A 2 kg mass is lifted 5 m. Find work done (g=10)', options: { A: '25 J', B: '50 J', C: '10 J', D: '100 J' }, answer: 'D', explanation: 'W = mgh = 2×10×5 = 100 J' },
  { id: 'phy-2013-7', subject: 'physics', topic: 'Energy & Work', year: 2013, question: 'Find KE of a 4 kg body moving at 3 m/s', options: { A: '6 J', B: '12 J', C: '18 J', D: '36 J' }, answer: 'C', explanation: 'KE = ½mv² = ½(4)(9) = 18 J' },
  { id: 'phy-2013-8', subject: 'physics', topic: 'Energy & Work', year: 2013, question: 'A machine has efficiency 80%. If input is 500 J, find output', options: { A: '450 J', B: '625 J', C: '100 J', D: '400 J' }, answer: 'D', explanation: 'Output = 80% × 500 = 400 J' },
  { id: 'phy-2013-9', subject: 'physics', topic: 'Energy & Work', year: 2013, question: 'Power is defined as', options: { A: 'Energy stored', B: 'Force × distance', C: 'Rate of doing work', D: 'Mass × velocity' }, answer: 'C', explanation: 'Power = Work/Time, which is the rate of doing work' },
  { id: 'phy-2013-10', subject: 'physics', topic: 'Energy & Work', year: 2013, question: 'A 10 N force moves an object 5 m at 60° to force. Find work', options: { A: '50 J', B: '25 J', C: '43.3 J', D: '10 J' }, answer: 'B', explanation: 'W = Fs cos60° = 10×5×0.5 = 25 J' },
  { id: 'phy-2013-11', subject: 'physics', topic: 'Waves & Sound', year: 2013, question: 'A wave has frequency 50 Hz and wavelength 2 m. Find velocity', options: { A: '52 m/s', B: '25 m/s', C: '100 m/s', D: '48 m/s' }, answer: 'C', explanation: 'v = fλ = 50 × 2 = 100 m/s' },
  { id: 'phy-2013-12', subject: 'physics', topic: 'Waves & Sound', year: 2013, question: 'The speed of sound in air is approximately', options: { A: '1500 m/s', B: '3×10⁸ m/s', C: '340 m/s', D: '1000 m/s' }, answer: 'C', explanation: 'Speed of sound in air ≈ 340 m/s at room temperature' },
  { id: 'phy-2013-13', subject: 'physics', topic: 'Waves & Sound', year: 2013, question: 'A vibrating string has fundamental frequency 200 Hz. Find 2nd harmonic', options: { A: '100 Hz', B: '400 Hz', C: '600 Hz', D: '300 Hz' }, answer: 'B', explanation: '2nd harmonic = 2 × fundamental = 2 × 200 = 400 Hz' },
  { id: 'phy-2013-14', subject: 'physics', topic: 'Waves & Sound', year: 2013, question: 'What type of wave is sound?', options: { A: 'Electromagnetic', B: 'Transverse', C: 'Longitudinal', D: 'Standing' }, answer: 'C', explanation: 'Sound is a longitudinal wave (compressions and rarefactions)' },
  { id: 'phy-2013-15', subject: 'physics', topic: 'Waves & Sound', year: 2013, question: 'An echo is heard 4s after a sound. Find distance to wall (v=340 m/s)', options: { A: '680 m', B: '1360 m', C: '340 m', D: '170 m' }, answer: 'A', explanation: 'Total distance = 340×4 = 1360 m. Distance to wall = 1360/2 = 680 m' },
  { id: 'phy-2013-16', subject: 'physics', topic: 'Electricity', year: 2013, question: 'Find current when V=12V and R=4Ω', options: { A: '48 A', B: '3 A', C: '0.33 A', D: '8 A' }, answer: 'B', explanation: 'I = V/R = 12/4 = 3 A' },
  { id: 'phy-2013-17', subject: 'physics', topic: 'Electricity', year: 2013, question: 'Three 6Ω resistors in parallel. Find total resistance', options: { A: '18Ω', B: '2Ω', C: '6Ω', D: '3Ω' }, answer: 'B', explanation: '1/R = 1/6+1/6+1/6 = 3/6 = 1/2. R = 2Ω' },
  { id: 'phy-2013-18', subject: 'physics', topic: 'Electricity', year: 2013, question: 'Find power dissipated when I=2A and R=5Ω', options: { A: '10 W', B: '20 W', C: '7 W', D: '25 W' }, answer: 'B', explanation: 'P = I²R = 4×5 = 20 W' },
  { id: 'phy-2013-19', subject: 'physics', topic: 'Electricity', year: 2013, question: 'The SI unit of electric charge is', options: { A: 'Ohm', B: 'Ampere', C: 'Volt', D: 'Coulomb' }, answer: 'D', explanation: 'Electric charge is measured in Coulombs (C)' },
  { id: 'phy-2013-20', subject: 'physics', topic: 'Electricity', year: 2013, question: 'Two 4Ω resistors in series. Find total resistance', options: { A: '16Ω', B: '2Ω', C: '4Ω', D: '8Ω' }, answer: 'D', explanation: 'Series: R = R₁+R₂ = 4+4 = 8Ω' },
  { id: 'phy-2013-21', subject: 'physics', topic: 'Heat & Thermodynamics', year: 2013, question: 'Convert 100°C to Kelvin', options: { A: '100 K', B: '273 K', C: '373 K', D: '473 K' }, answer: 'C', explanation: 'T(K) = T(°C) + 273 = 100 + 273 = 373 K' },
  { id: 'phy-2013-22', subject: 'physics', topic: 'Heat & Thermodynamics', year: 2013, question: 'Heat needed to raise 2 kg of water by 5°C (c=4200 J/kg°C)', options: { A: '21000 J', B: '42000 J', C: '4200 J', D: '84000 J' }, answer: 'B', explanation: 'Q = mcΔT = 2×4200×5 = 42000 J' },
  { id: 'phy-2013-23', subject: 'physics', topic: 'Heat & Thermodynamics', year: 2013, question: 'At what temperature are Celsius and Fahrenheit equal?', options: { A: '100°', B: '0°', C: '-40°', D: '-273°' }, answer: 'C', explanation: 'C = (F-32)×5/9. If C=F: C = (C-32)×5/9. 9C=5C-160. 4C=-160. C=-40' },
  { id: 'phy-2013-24', subject: 'physics', topic: 'Heat & Thermodynamics', year: 2013, question: 'Which method of heat transfer does not require a medium?', options: { A: 'Radiation', B: 'Conduction', C: 'Convection', D: 'All require medium' }, answer: 'A', explanation: 'Radiation can travel through vacuum (e.g., sun to earth)' },
  { id: 'phy-2013-25', subject: 'physics', topic: 'Heat & Thermodynamics', year: 2013, question: 'A gas at 300K is heated to 600K at constant volume. Pressure will', options: { A: 'Halve', B: 'Double', C: 'Stay same', D: 'Triple' }, answer: 'B', explanation: 'P/T = constant. If T doubles, P doubles (Pressure Law)' },
  { id: 'phy-2013-26', subject: 'physics', topic: 'Optics', year: 2013, question: 'The angle of incidence equals angle of reflection is the law of', options: { A: 'Reflection', B: 'Refraction', C: 'Diffraction', D: 'Polarization' }, answer: 'A', explanation: 'This is the first law of reflection' },
  { id: 'phy-2013-27', subject: 'physics', topic: 'Optics', year: 2013, question: 'A concave mirror has focal length 10 cm. Find radius of curvature', options: { A: '10 cm', B: '5 cm', C: '20 cm', D: '40 cm' }, answer: 'C', explanation: 'R = 2f = 2×10 = 20 cm' },
  { id: 'phy-2013-28', subject: 'physics', topic: 'Optics', year: 2013, question: 'Refractive index of glass is 1.5. Find speed of light in glass (c=3×10⁸)', options: { A: '3×10⁸ m/s', B: '4.5×10⁸ m/s', C: '1.5×10⁸ m/s', D: '2×10⁸ m/s' }, answer: 'D', explanation: 'n = c/v. v = c/n = 3×10⁸/1.5 = 2×10⁸ m/s' },
  { id: 'phy-2013-29', subject: 'physics', topic: 'Optics', year: 2013, question: 'A converging lens has power +5 D. Find focal length', options: { A: '20 m', B: '5 m', C: '0.2 m', D: '0.5 m' }, answer: 'C', explanation: 'P = 1/f. f = 1/5 = 0.2 m' },
  { id: 'phy-2013-30', subject: 'physics', topic: 'Optics', year: 2013, question: 'Total internal reflection occurs when light travels from', options: { A: 'Dense to less dense medium', B: 'Less dense to dense medium', C: 'Vacuum to glass', D: 'Air to water' }, answer: 'A', explanation: 'TIR occurs when light goes from optically denser to less dense medium' },
  { id: 'phy-2013-31', subject: 'physics', topic: 'Modern Physics', year: 2013, question: 'The energy of a photon is E = hf. If frequency doubles, energy', options: { A: 'Halves', B: 'Doubles', C: 'Stays same', D: 'Quadruples' }, answer: 'B', explanation: 'E = hf. If f→2f, then E→2hf = 2E' },
  { id: 'phy-2013-32', subject: 'physics', topic: 'Modern Physics', year: 2013, question: 'Radioactive half-life of a substance is 4 hours. Fraction left after 12 hours', options: { A: '1/2', B: '1/4', C: '1/8', D: '1/16' }, answer: 'C', explanation: '12/4 = 3 half-lives. Fraction = (1/2)³ = 1/8' },
  { id: 'phy-2013-33', subject: 'physics', topic: 'Modern Physics', year: 2013, question: 'In photoelectric effect, increasing intensity increases', options: { A: 'KE of electrons', B: 'Number of electrons', C: 'Frequency', D: 'Wavelength' }, answer: 'B', explanation: 'Intensity affects number of photoelectrons, not their KE' },
  { id: 'phy-2013-34', subject: 'physics', topic: 'Modern Physics', year: 2013, question: 'Alpha particles are', options: { A: 'Photons', B: 'Electrons', C: 'Neutrons', D: 'Helium nuclei' }, answer: 'D', explanation: 'Alpha particles are helium nuclei (2 protons + 2 neutrons)' },
  { id: 'phy-2013-35', subject: 'physics', topic: 'Modern Physics', year: 2013, question: 'The work function of a metal is the', options: { A: 'Frequency of light', B: 'Maximum KE of electron', C: 'Energy of photon', D: 'Minimum energy to eject electron' }, answer: 'D', explanation: 'Work function is the minimum energy needed to remove an electron from metal surface' },
  { id: 'phy-2013-36', subject: 'physics', topic: 'Gravitation & Pressure', year: 2013, question: 'Atmospheric pressure is approximately', options: { A: '1.0×10¹ Pa', B: '1.0×10³ Pa', C: '1.0×10⁸ Pa', D: '1.0×10⁵ Pa' }, answer: 'D', explanation: 'Standard atmospheric pressure ≈ 1.013×10⁵ Pa' },
  { id: 'phy-2013-37', subject: 'physics', topic: 'Gravitation & Pressure', year: 2013, question: 'Pressure at depth h in a liquid of density ρ is', options: { A: 'ρg/h', B: 'ρgh', C: 'ρh/g', D: 'gh/ρ' }, answer: 'B', explanation: 'Pressure = ρgh (density × gravity × depth)' },
  { id: 'phy-2013-38', subject: 'physics', topic: 'Gravitation & Pressure', year: 2013, question: 'A hydraulic press has area ratio 1:10. If input force is 50N, find output', options: { A: '50 N', B: '5 N', C: '500 N', D: '5000 N' }, answer: 'C', explanation: 'F₂/F₁ = A₂/A₁. F₂ = 50×10 = 500 N' },
  { id: 'phy-2013-39', subject: 'physics', topic: 'Gravitation & Pressure', year: 2013, question: 'An object weighs 10 N in air and 6 N in water. Find upthrust', options: { A: '6 N', B: '4 N', C: '16 N', D: '10 N' }, answer: 'B', explanation: 'Upthrust = Weight in air - Weight in water = 10-6 = 4 N' },
  { id: 'phy-2013-40', subject: 'physics', topic: 'Gravitation & Pressure', year: 2013, question: 'The SI unit of pressure is', options: { A: 'Newton', B: 'Pascal', C: 'Joule', D: 'Watt' }, answer: 'B', explanation: 'Pressure is measured in Pascals (Pa = N/m²)' },
  { id: 'phy-2013-41', subject: 'physics', topic: 'Electromagnetic Field', year: 2013, question: 'The force on a charge q moving at v in field B is', options: { A: 'qv/B', B: 'qvB cosθ', C: 'qvB sinθ', D: 'qB/v' }, answer: 'C', explanation: 'Lorentz force: F = qvB sinθ' },
  { id: 'phy-2013-42', subject: 'physics', topic: 'Electromagnetic Field', year: 2013, question: 'Faraday\'s law states that induced EMF is proportional to', options: { A: 'Resistance of coil', B: 'Magnetic field strength', C: 'Current in wire', D: 'Rate of change of flux' }, answer: 'D', explanation: 'EMF = -dΦ/dt (rate of change of magnetic flux)' },
  { id: 'phy-2013-43', subject: 'physics', topic: 'Electromagnetic Field', year: 2013, question: 'A transformer with 100 primary and 500 secondary turns. If Vp=20V, find Vs', options: { A: '50 V', B: '4 V', C: '2500 V', D: '100 V' }, answer: 'D', explanation: 'Vs/Vp = Ns/Np. Vs = 20×500/100 = 100 V' },
  { id: 'phy-2013-44', subject: 'physics', topic: 'Electromagnetic Field', year: 2013, question: 'The unit of magnetic flux is', options: { A: 'Henry', B: 'Tesla', C: 'Weber', D: 'Farad' }, answer: 'C', explanation: 'Magnetic flux is measured in Weber (Wb)' },
  { id: 'phy-2013-45', subject: 'physics', topic: 'Electromagnetic Field', year: 2013, question: 'Lenz\'s law is a consequence of conservation of', options: { A: 'Charge', B: 'Energy', C: 'Mass', D: 'Momentum' }, answer: 'B', explanation: 'Lenz\'s law: induced current opposes the change, conserving energy' },
  { id: 'che-2013-1', subject: 'chemistry', topic: 'Atomic Structure', year: 2013, question: 'The atomic number of an element is the number of', options: { A: 'Neutrons', B: 'Protons', C: 'Electrons', D: 'Nucleons' }, answer: 'B', explanation: 'Atomic number (Z) = number of protons in the nucleus' },
  { id: 'che-2013-2', subject: 'chemistry', topic: 'Atomic Structure', year: 2013, question: 'An isotope of carbon-12 has', options: { A: '12 neutrons', B: '12 protons', C: '6 protons, 12 neutrons', D: '6 protons, 6 neutrons' }, answer: 'D', explanation: 'C-12: Z=6 (protons), mass=12, neutrons=12-6=6' },
  { id: 'che-2013-3', subject: 'chemistry', topic: 'Atomic Structure', year: 2013, question: 'The maximum number of electrons in the 3rd shell is', options: { A: '18', B: '8', C: '2', D: '32' }, answer: 'A', explanation: 'Maximum = 2n² = 2(3²) = 18' },
  { id: 'che-2013-4', subject: 'chemistry', topic: 'Atomic Structure', year: 2013, question: 'Which quantum number describes the shape of an orbital?', options: { A: 'Azimuthal (l)', B: 'Principal (n)', C: 'Magnetic (ml)', D: 'Spin (ms)' }, answer: 'A', explanation: 'l (azimuthal/angular momentum) determines orbital shape: s,p,d,f' },
  { id: 'che-2013-5', subject: 'chemistry', topic: 'Atomic Structure', year: 2013, question: 'Isotopes of an element have same', options: { A: 'Atomic number', B: 'Mass number', C: 'Number of neutrons', D: 'Density' }, answer: 'A', explanation: 'Isotopes have same atomic number (protons) but different mass numbers' },
  { id: 'che-2013-6', subject: 'chemistry', topic: 'Chemical Bonding', year: 2013, question: 'NaCl is an example of', options: { A: 'Covalent bond', B: 'Ionic bond', C: 'Metallic bond', D: 'Hydrogen bond' }, answer: 'B', explanation: 'Na (metal) transfers electron to Cl (non-metal) forming ionic bond' },
  { id: 'che-2013-7', subject: 'chemistry', topic: 'Chemical Bonding', year: 2013, question: 'How many covalent bonds does carbon form?', options: { A: '2', B: '4', C: '3', D: '1' }, answer: 'B', explanation: 'Carbon has 4 valence electrons and forms 4 covalent bonds' },
  { id: 'che-2013-8', subject: 'chemistry', topic: 'Chemical Bonding', year: 2013, question: 'The shape of methane (CH₄) is', options: { A: 'Octahedral', B: 'Linear', C: 'Trigonal planar', D: 'Tetrahedral' }, answer: 'D', explanation: 'CH₄: 4 bond pairs, no lone pairs = tetrahedral' },
  { id: 'che-2013-9', subject: 'chemistry', topic: 'Chemical Bonding', year: 2013, question: 'Which bond is the strongest?', options: { A: 'Ionic', B: 'Van der Waals', C: 'Hydrogen bond', D: 'Dipole-dipole' }, answer: 'A', explanation: 'Ionic bonds (electrostatic attraction) are generally strongest of these' },
  { id: 'che-2013-10', subject: 'chemistry', topic: 'Chemical Bonding', year: 2013, question: 'Diamond is hard because of', options: { A: 'Weak intermolecular forces', B: 'Ionic bonds', C: 'Metallic bonds', D: 'Strong covalent bonds in 3D network' }, answer: 'D', explanation: 'Diamond has a giant covalent structure with strong C-C bonds in all directions' },
  { id: 'che-2013-11', subject: 'chemistry', topic: 'Stoichiometry', year: 2013, question: 'How many moles in 44g of CO₂? (C=12, O=16)', options: { A: '44 mol', B: '2 mol', C: '0.5 mol', D: '1 mol' }, answer: 'D', explanation: 'Molar mass CO₂ = 12+32 = 44 g/mol. Moles = 44/44 = 1' },
  { id: 'che-2013-12', subject: 'chemistry', topic: 'Stoichiometry', year: 2013, question: 'What volume does 1 mol of gas occupy at STP?', options: { A: '44.8 L', B: '22.4 cm³', C: '11.2 L', D: '22.4 L' }, answer: 'D', explanation: 'At STP, 1 mole of any gas occupies 22.4 dm³ (litres)' },
  { id: 'che-2013-13', subject: 'chemistry', topic: 'Stoichiometry', year: 2013, question: 'In 2H₂ + O₂ → 2H₂O, moles of O₂ needed for 4 mol H₂', options: { A: '1 mol', B: '4 mol', C: '2 mol', D: '8 mol' }, answer: 'C', explanation: 'Ratio H₂:O₂ = 2:1. For 4 mol H₂, need 4/2 = 2 mol O₂' },
  { id: 'che-2013-14', subject: 'chemistry', topic: 'Stoichiometry', year: 2013, question: 'The empirical formula of C₆H₁₂O₆ is', options: { A: 'CH₂O', B: 'C₂H₄O₂', C: 'C₃H₆O₃', D: 'CHO' }, answer: 'A', explanation: 'Divide by smallest: C₆H₁₂O₆ → ratio 1:2:1 → CH₂O' },
  { id: 'che-2013-15', subject: 'chemistry', topic: 'Stoichiometry', year: 2013, question: 'Avogadro\'s number is approximately', options: { A: '6.02×10²³', B: '6.02×10²²', C: '3.01×10²³', D: '6.02×10²⁴' }, answer: 'A', explanation: 'Avogadro\'s constant = 6.022 × 10²³ mol⁻¹' },
  { id: 'che-2013-16', subject: 'chemistry', topic: 'Acids, Bases & Salts', year: 2013, question: 'What is the pH of a neutral solution?', options: { A: '14', B: '0', C: '7', D: '1' }, answer: 'C', explanation: 'Neutral pH = 7. Below 7 is acidic, above 7 is basic' },
  { id: 'che-2013-17', subject: 'chemistry', topic: 'Acids, Bases & Salts', year: 2013, question: 'Which acid is found in car batteries?', options: { A: 'HNO₃', B: 'HCl', C: 'H₂SO₄', D: 'CH₃COOH' }, answer: 'C', explanation: 'Sulphuric acid (H₂SO₄) is used in lead-acid batteries' },
  { id: 'che-2013-18', subject: 'chemistry', topic: 'Acids, Bases & Salts', year: 2013, question: 'NaOH + HCl → ?', options: { A: 'NaCl + H₂O', B: 'NaH + ClOH', C: 'NaCl + H₂', D: 'Na + HClO' }, answer: 'A', explanation: 'Acid + Base → Salt + Water. NaOH+HCl → NaCl+H₂O' },
  { id: 'che-2013-19', subject: 'chemistry', topic: 'Acids, Bases & Salts', year: 2013, question: 'A substance with pH 3 is', options: { A: 'Neutral', B: 'Weakly acidic', C: 'Strongly acidic', D: 'Basic' }, answer: 'C', explanation: 'pH 3 is strongly acidic (far below 7)' },
  { id: 'che-2013-20', subject: 'chemistry', topic: 'Acids, Bases & Salts', year: 2013, question: 'The basicity of H₃PO₄ is', options: { A: '4', B: '1', C: '2', D: '3' }, answer: 'D', explanation: 'H₃PO₄ has 3 replaceable hydrogen atoms, so basicity = 3' },
  { id: 'che-2013-21', subject: 'chemistry', topic: 'Organic Chemistry', year: 2013, question: 'The IUPAC name of CH₃CH₂OH is', options: { A: 'Methanol', B: 'Ethanol', C: 'Propanol', D: 'Butanol' }, answer: 'B', explanation: '2 carbons + OH group = ethanol' },
  { id: 'che-2013-22', subject: 'chemistry', topic: 'Organic Chemistry', year: 2013, question: 'The functional group of aldehydes is', options: { A: '-OH', B: '-COOH', C: '-CO-', D: '-CHO' }, answer: 'D', explanation: 'Aldehydes have the -CHO (formyl) functional group' },
  { id: 'che-2013-23', subject: 'chemistry', topic: 'Organic Chemistry', year: 2013, question: 'Ethene undergoes', options: { A: 'Addition reaction', B: 'Substitution reaction', C: 'Elimination reaction', D: 'Condensation' }, answer: 'A', explanation: 'Alkenes (C=C) undergo addition reactions (e.g., with Br₂, H₂, HCl)' },
  { id: 'che-2013-24', subject: 'chemistry', topic: 'Organic Chemistry', year: 2013, question: 'The general formula for alkanes is', options: { A: 'CₙH₂ₙ₋₂', B: 'CₙH₂ₙ', C: 'CₙH₂ₙ₊₂', D: 'CₙHₙ' }, answer: 'C', explanation: 'Alkanes: CₙH₂ₙ₊₂ (saturated hydrocarbons)' },
  { id: 'che-2013-25', subject: 'chemistry', topic: 'Organic Chemistry', year: 2013, question: 'Isomers have the same', options: { A: 'Structural formula', B: 'Molecular formula', C: 'Physical properties', D: 'Functional group' }, answer: 'B', explanation: 'Isomers share molecular formula but differ in structure' },
  { id: 'che-2013-26', subject: 'chemistry', topic: 'Electrochemistry', year: 2013, question: 'In electrolysis of brine, gas produced at anode is', options: { A: 'Chlorine', B: 'Hydrogen', C: 'Oxygen', D: 'Sodium' }, answer: 'A', explanation: 'Cl⁻ ions are discharged at the anode: 2Cl⁻ → Cl₂ + 2e⁻' },
  { id: 'che-2013-27', subject: 'chemistry', topic: 'Electrochemistry', year: 2013, question: 'The SI unit of quantity of electricity is', options: { A: 'Volt', B: 'Ampere', C: 'Coulomb', D: 'Farad' }, answer: 'C', explanation: 'Q = It, measured in Coulombs' },
  { id: 'che-2013-28', subject: 'chemistry', topic: 'Electrochemistry', year: 2013, question: 'One faraday is equal to', options: { A: '9650 C', B: '96500 C', C: '965 C', D: '965000 C' }, answer: 'B', explanation: '1 Faraday = 96,485 ≈ 96,500 Coulombs' },
  { id: 'che-2013-29', subject: 'chemistry', topic: 'Electrochemistry', year: 2013, question: 'During electrolysis, reduction occurs at the', options: { A: 'Anode', B: 'Cathode', C: 'Both electrodes', D: 'Electrolyte' }, answer: 'B', explanation: 'Cathode: reduction (gain of electrons). Anode: oxidation' },
  { id: 'che-2013-30', subject: 'chemistry', topic: 'Electrochemistry', year: 2013, question: 'Which metal is used to electroplate iron to prevent rusting?', options: { A: 'Gold', B: 'Copper', C: 'Zinc', D: 'Silver' }, answer: 'C', explanation: 'Galvanization: coating iron with zinc to prevent rusting' },
  { id: 'che-2013-31', subject: 'chemistry', topic: 'Periodic Table', year: 2013, question: 'Elements in the same group have the same number of', options: { A: 'Total electrons', B: 'Valence electrons', C: 'Neutrons', D: 'Energy levels' }, answer: 'B', explanation: 'Same group = same number of valence (outer shell) electrons' },
  { id: 'che-2013-32', subject: 'chemistry', topic: 'Periodic Table', year: 2013, question: 'Across a period, atomic radius', options: { A: 'Decreases', B: 'Increases', C: 'Stays same', D: 'First increases then decreases' }, answer: 'A', explanation: 'Across period: more protons pull electrons closer, radius decreases' },
  { id: 'che-2013-33', subject: 'chemistry', topic: 'Periodic Table', year: 2013, question: 'Noble gases are unreactive because they have', options: { A: 'One valence electron', B: 'Empty outer shell', C: 'Full outer shell', D: 'High electronegativity' }, answer: 'C', explanation: 'Noble gases have complete octet (or duplet for He) - stable configuration' },
  { id: 'che-2013-34', subject: 'chemistry', topic: 'Periodic Table', year: 2013, question: 'The most electronegative element is', options: { A: 'Nitrogen', B: 'Oxygen', C: 'Chlorine', D: 'Fluorine' }, answer: 'D', explanation: 'Fluorine has the highest electronegativity (3.98 on Pauling scale)' },
  { id: 'che-2013-35', subject: 'chemistry', topic: 'Periodic Table', year: 2013, question: 'Alkali metals are in Group', options: { A: 'I', B: 'II', C: 'VII', D: 'VIII' }, answer: 'A', explanation: 'Alkali metals (Li, Na, K...) are in Group I with 1 valence electron' },
  { id: 'che-2013-36', subject: 'chemistry', topic: 'Gas Laws', year: 2013, question: 'At constant temperature, PV = constant is', options: { A: 'Boyle\'s Law', B: 'Charles\' Law', C: 'Avogadro\'s Law', D: 'Dalton\'s Law' }, answer: 'A', explanation: 'Boyle\'s Law: PV = k at constant temperature' },
  { id: 'che-2013-37', subject: 'chemistry', topic: 'Gas Laws', year: 2013, question: 'A gas at 2 atm occupies 10L. Find volume at 5 atm (constant T)', options: { A: '20 L', B: '25 L', C: '4 L', D: '2 L' }, answer: 'C', explanation: 'P₁V₁=P₂V₂. 2×10=5×V₂. V₂=4L' },
  { id: 'che-2013-38', subject: 'chemistry', topic: 'Gas Laws', year: 2013, question: 'Charles\' Law states that at constant pressure', options: { A: 'V ∝ 1/T', B: 'P ∝ T', C: 'V ∝ T', D: 'P ∝ 1/V' }, answer: 'C', explanation: 'Charles\' Law: V/T = constant, so V is proportional to T (in Kelvin)' },
  { id: 'che-2013-39', subject: 'chemistry', topic: 'Gas Laws', year: 2013, question: 'STP conditions are', options: { A: '298K and 1 atm', B: '273K and 1 atm', C: '373K and 1 atm', D: '0K and 1 atm' }, answer: 'B', explanation: 'Standard Temperature and Pressure: 273K (0°C) and 1 atmosphere' },
  { id: 'che-2013-40', subject: 'chemistry', topic: 'Gas Laws', year: 2013, question: 'In PV=nRT, R is the', options: { A: 'Universal gas constant', B: 'Resistance', C: 'Radius', D: 'Rate constant' }, answer: 'A', explanation: 'R = 8.314 J/(mol·K) is the universal/molar gas constant' },
  { id: 'che-2013-41', subject: 'chemistry', topic: 'Redox Reactions', year: 2013, question: 'Oxidation is', options: { A: 'Gain of electrons', B: 'Loss of electrons', C: 'Loss of protons', D: 'Gain of protons' }, answer: 'B', explanation: 'OIL RIG: Oxidation Is Loss (of electrons)' },
  { id: 'che-2013-42', subject: 'chemistry', topic: 'Redox Reactions', year: 2013, question: 'In Fe₂O₃ + 3CO → 2Fe + 3CO₂, Fe₂O₃ is', options: { A: 'Reduced', B: 'Oxidized', C: 'Neither', D: 'Both' }, answer: 'A', explanation: 'Fe goes from +3 to 0 (gains electrons) = reduced' },
  { id: 'che-2013-43', subject: 'chemistry', topic: 'Redox Reactions', year: 2013, question: 'The oxidation number of Mn in KMnO₄ is', options: { A: '+7', B: '+4', C: '+2', D: '+6' }, answer: 'A', explanation: 'K(+1) + Mn + 4O(-2)=0. 1+Mn-8=0. Mn=+7' },
  { id: 'che-2013-44', subject: 'chemistry', topic: 'Redox Reactions', year: 2013, question: 'A reducing agent is a substance that', options: { A: 'Accepts protons', B: 'Accepts electrons', C: 'Donates protons', D: 'Donates electrons' }, answer: 'D', explanation: 'Reducing agent donates electrons (gets oxidized itself)' },
  { id: 'che-2013-45', subject: 'chemistry', topic: 'Redox Reactions', year: 2013, question: 'Which is a strong oxidizing agent?', options: { A: 'KMnO₄', B: 'NaCl', C: 'H₂O', D: 'CO₂' }, answer: 'A', explanation: 'KMnO₄ (potassium permanganate) is a powerful oxidizing agent' },
  { id: 'eng-2013-1', subject: 'english', topic: 'Comprehension', year: 2013, question: 'In a passage, "ubiquitous" most nearly means', options: { A: 'Rare', B: 'Found everywhere', C: 'Beautiful', D: 'Dangerous' }, answer: 'B', explanation: 'Ubiquitous means present, appearing, or found everywhere' },
  { id: 'eng-2013-2', subject: 'english', topic: 'Comprehension', year: 2013, question: '"The author\'s tone in the passage is best described as"', options: { A: 'Hostile', B: 'Reflective', C: 'Indifferent', D: 'Humorous' }, answer: 'B', explanation: 'When an author examines ideas thoughtfully, the tone is reflective' },
  { id: 'eng-2013-3', subject: 'english', topic: 'Comprehension', year: 2013, question: 'An antonym of "benevolent" is', options: { A: 'Charitable', B: 'Generous', C: 'Kind', D: 'Malevolent' }, answer: 'D', explanation: 'Benevolent means kind/generous; malevolent means wishing harm' },
  { id: 'eng-2013-4', subject: 'english', topic: 'Comprehension', year: 2013, question: '"Ephemeral" means', options: { A: 'Eternal', B: 'Short-lived', C: 'Powerful', D: 'Expensive' }, answer: 'B', explanation: 'Ephemeral: lasting for a very short time' },
  { id: 'eng-2013-5', subject: 'english', topic: 'Comprehension', year: 2013, question: 'The word "pragmatic" means', options: { A: 'Emotional', B: 'Theoretical', C: 'Practical', D: 'Spiritual' }, answer: 'C', explanation: 'Pragmatic: dealing with things sensibly and realistically' },
  { id: 'eng-2013-6', subject: 'english', topic: 'Oral English - Vowels', year: 2013, question: 'The vowel sound in "beat" is', options: { A: '/æ/', B: '/ɪ/', C: '/e/', D: '/iː/' }, answer: 'D', explanation: '"beat" has the long vowel /iː/ (as in see, meet, feat)' },
  { id: 'eng-2013-7', subject: 'english', topic: 'Oral English - Vowels', year: 2013, question: 'Which word has the vowel sound /æ/?', options: { A: 'cut', B: 'cat', C: 'cot', D: 'coat' }, answer: 'B', explanation: '/æ/ is the short a sound as in cat, bat, hat' },
  { id: 'eng-2013-8', subject: 'english', topic: 'Oral English - Vowels', year: 2013, question: 'The "ou" in "bought" sounds like', options: { A: '/aʊ/', B: '/ɔː/', C: '/uː/', D: '/əʊ/' }, answer: 'B', explanation: '"bought" has the /ɔː/ sound (also in caught, taught)' },
  { id: 'eng-2013-9', subject: 'english', topic: 'Oral English - Vowels', year: 2013, question: 'Which pair contains the same vowel sound?', options: { A: 'bit, beat', B: 'seat, set', C: 'seat, beat', D: 'cat, cart' }, answer: 'C', explanation: 'seat and beat both contain /iː/' },
  { id: 'eng-2013-10', subject: 'english', topic: 'Oral English - Vowels', year: 2013, question: 'The vowel in "bird" is', options: { A: '/iː/', B: '/ɪ/', C: '/aɪ/', D: '/ɜː/' }, answer: 'D', explanation: '"bird" contains the long central vowel /ɜː/ (also in word, hurt)' },
  { id: 'eng-2013-11', subject: 'english', topic: 'Oral English - Consonants', year: 2013, question: 'The "th" in "think" is', options: { A: '/t/', B: '/ð/ (voiced)', C: '/θ/ (voiceless)', D: '/s/' }, answer: 'C', explanation: '"think" has voiceless /θ/. "this" has voiced /ð/' },
  { id: 'eng-2013-12', subject: 'english', topic: 'Oral English - Consonants', year: 2013, question: 'Which word begins with /ʃ/?', options: { A: 'the', B: 'see', C: 'zoo', D: 'shoe' }, answer: 'D', explanation: '/ʃ/ is the "sh" sound as in shoe, ship, shall' },
  { id: 'eng-2013-13', subject: 'english', topic: 'Oral English - Consonants', year: 2013, question: 'The "g" in "gym" sounds like', options: { A: '/k/', B: '/g/', C: '/ʒ/', D: '/dʒ/' }, answer: 'D', explanation: '"gym" starts with /dʒ/ (soft g, same as j in "jump")' },
  { id: 'eng-2013-14', subject: 'english', topic: 'Oral English - Consonants', year: 2013, question: 'How many consonant sounds are in English?', options: { A: '24', B: '21', C: '26', D: '20' }, answer: 'A', explanation: 'English has 24 consonant phonemes' },
  { id: 'eng-2013-15', subject: 'english', topic: 'Oral English - Consonants', year: 2013, question: 'The "ph" in "phone" sounds like', options: { A: '/p/', B: '/f/', C: '/v/', D: '/h/' }, answer: 'B', explanation: '"ph" in phone represents /f/ sound' },
  { id: 'eng-2013-16', subject: 'english', topic: 'Oral English - Stress', year: 2013, question: 'In "photograph", primary stress falls on', options: { A: 'Second syllable', B: 'First syllable', C: 'Third syllable', D: 'Last syllable' }, answer: 'B', explanation: 'PHO-to-graph: stress on first syllable' },
  { id: 'eng-2013-17', subject: 'english', topic: 'Oral English - Stress', year: 2013, question: 'In "below", the stress is on', options: { A: 'Second syllable', B: 'First syllable', C: 'Both equally', D: 'Neither' }, answer: 'A', explanation: 'be-LOW: stress on second syllable' },
  { id: 'eng-2013-18', subject: 'english', topic: 'Oral English - Stress', year: 2013, question: 'Which word has stress on the second syllable?', options: { A: 'table', B: 'never', C: 'begin', D: 'present (noun)' }, answer: 'C', explanation: 'be-GIN has stress on second syllable' },
  { id: 'eng-2013-19', subject: 'english', topic: 'Oral English - Stress', year: 2013, question: 'Two-syllable nouns in English usually stress the', options: { A: 'First syllable', B: 'Second syllable', C: 'Both equally', D: 'Last syllable' }, answer: 'A', explanation: 'General rule: 2-syllable nouns stress 1st syllable (TA-ble, WA-ter)' },
  { id: 'eng-2013-20', subject: 'english', topic: 'Oral English - Stress', year: 2013, question: 'In "education", primary stress is on', options: { A: 'First syllable', B: 'Third syllable', C: 'Second syllable', D: 'Fourth syllable' }, answer: 'B', explanation: 'e-du-CA-tion: stress on third syllable' },
  { id: 'eng-2013-21', subject: 'english', topic: 'Sentence Interpretation', year: 2013, question: '"He kicked the bucket" means', options: { A: 'He kicked a bucket', B: 'He died', C: 'He was angry', D: 'He played football' }, answer: 'B', explanation: '"Kick the bucket" is an idiom meaning to die' },
  { id: 'eng-2013-22', subject: 'english', topic: 'Sentence Interpretation', year: 2013, question: '"To let the cat out of the bag" means', options: { A: 'To reveal a secret', B: 'To free a cat', C: 'To be careless', D: 'To go shopping' }, answer: 'A', explanation: 'This idiom means to reveal a secret accidentally' },
  { id: 'eng-2013-23', subject: 'english', topic: 'Sentence Interpretation', year: 2013, question: '"A bird in the hand is worth two in the bush" means', options: { A: 'What you have is more valuable than what you might get', B: 'Birds are valuable', C: 'Two is better than one', D: 'Bushes have birds' }, answer: 'A', explanation: 'It means something you already have is better than something uncertain' },
  { id: 'eng-2013-24', subject: 'english', topic: 'Sentence Interpretation', year: 2013, question: '"He is burning the midnight oil" means', options: { A: 'He is studying late', B: 'He is wasting oil', C: 'He is cooking', D: 'He started a fire' }, answer: 'A', explanation: 'This idiom means staying up late to study or work' },
  { id: 'eng-2013-25', subject: 'english', topic: 'Sentence Interpretation', year: 2013, question: '"She has a green thumb" means', options: { A: 'Her thumb is green', B: 'She is good at gardening', C: 'She is sick', D: 'She paints' }, answer: 'B', explanation: '"Green thumb" means natural talent for growing plants' },
  { id: 'eng-2013-26', subject: 'english', topic: 'Grammar - Tenses', year: 2013, question: 'Choose the correct option: She ___ to school every day', options: { A: 'goes', B: 'go', C: 'going', D: 'gone' }, answer: 'A', explanation: 'Simple present with 3rd person singular: she goes' },
  { id: 'eng-2013-27', subject: 'english', topic: 'Grammar - Tenses', year: 2013, question: 'The past tense of "begin" is', options: { A: 'began', B: 'begun', C: 'beginned', D: 'beginning' }, answer: 'A', explanation: 'begin-began-begun (irregular verb)' },
  { id: 'eng-2013-28', subject: 'english', topic: 'Grammar - Tenses', year: 2013, question: 'She ___ her homework before she watched TV', options: { A: 'finished', B: 'has finished', C: 'had finished', D: 'finishes' }, answer: 'C', explanation: 'Past perfect (had + past participle) for action completed before another past action' },
  { id: 'eng-2013-29', subject: 'english', topic: 'Grammar - Tenses', year: 2013, question: 'By next year, I ___ my degree', options: { A: 'will have completed', B: 'will complete', C: 'complete', D: 'completed' }, answer: 'A', explanation: 'Future perfect: will have + past participle for action completed before future time' },
  { id: 'eng-2013-30', subject: 'english', topic: 'Grammar - Tenses', year: 2013, question: 'They ___ football when it started raining', options: { A: 'played', B: 'were playing', C: 'play', D: 'are playing' }, answer: 'B', explanation: 'Past continuous for action in progress when another action occurred' },
  { id: 'eng-2013-31', subject: 'english', topic: 'Grammar - Parts of Speech', year: 2013, question: 'In "The boy runs quickly", "quickly" is', options: { A: 'Noun', B: 'Adjective', C: 'Adverb', D: 'Verb' }, answer: 'C', explanation: '"quickly" modifies the verb "runs" = adverb' },
  { id: 'eng-2013-32', subject: 'english', topic: 'Grammar - Parts of Speech', year: 2013, question: 'A pronoun replaces a', options: { A: 'Adverb', B: 'Verb', C: 'Adjective', D: 'Noun' }, answer: 'D', explanation: 'Pronouns (he, she, it, they) replace nouns' },
  { id: 'eng-2013-33', subject: 'english', topic: 'Grammar - Parts of Speech', year: 2013, question: 'In "beautiful garden", "beautiful" is', options: { A: 'Adverb', B: 'Adjective', C: 'Noun', D: 'Pronoun' }, answer: 'B', explanation: '"beautiful" describes the noun "garden" = adjective' },
  { id: 'eng-2013-34', subject: 'english', topic: 'Grammar - Parts of Speech', year: 2013, question: 'Which is a conjunction?', options: { A: 'quickly', B: 'but', C: 'under', D: 'beautiful' }, answer: 'B', explanation: '"but" joins clauses/sentences = conjunction' },
  { id: 'eng-2013-35', subject: 'english', topic: 'Grammar - Parts of Speech', year: 2013, question: 'A preposition shows', options: { A: 'Time only', B: 'Action', C: 'Description', D: 'Relationship between nouns' }, answer: 'D', explanation: 'Prepositions (in, on, at, under) show relationship between nouns in space/time' },
  { id: 'eng-2013-36', subject: 'english', topic: 'Lexis - Synonyms & Antonyms', year: 2013, question: 'A synonym of "enormous" is', options: { A: 'Tiny', B: 'Huge', C: 'Average', D: 'Narrow' }, answer: 'B', explanation: 'Enormous and huge both mean very large' },
  { id: 'eng-2013-37', subject: 'english', topic: 'Lexis - Synonyms & Antonyms', year: 2013, question: 'An antonym of "transparent" is', options: { A: 'Bright', B: 'Clear', C: 'Visible', D: 'Opaque' }, answer: 'D', explanation: 'Transparent = see-through; opaque = cannot see through' },
  { id: 'eng-2013-38', subject: 'english', topic: 'Lexis - Synonyms & Antonyms', year: 2013, question: 'A synonym of "commence" is', options: { A: 'Pause', B: 'End', C: 'Continue', D: 'Begin' }, answer: 'D', explanation: 'Commence means to begin or start' },
  { id: 'eng-2013-39', subject: 'english', topic: 'Lexis - Synonyms & Antonyms', year: 2013, question: '"Affluent" is closest in meaning to', options: { A: 'Poor', B: 'Wealthy', C: 'Intelligent', D: 'Famous' }, answer: 'B', explanation: 'Affluent means having a great deal of money; wealthy' },
  { id: 'eng-2013-40', subject: 'english', topic: 'Lexis - Synonyms & Antonyms', year: 2013, question: 'The opposite of "verbose" is', options: { A: 'Concise', B: 'Wordy', C: 'Detailed', D: 'Long' }, answer: 'A', explanation: 'Verbose = using too many words; concise = brief and clear' },
  { id: 'eng-2013-41', subject: 'english', topic: 'Register & Varieties', year: 2013, question: 'The expression "The court is adjourned" belongs to ___ register', options: { A: 'Legal', B: 'Medical', C: 'Scientific', D: 'Religious' }, answer: 'A', explanation: '"Adjourn" is legal language for temporarily ending a court session' },
  { id: 'eng-2013-42', subject: 'english', topic: 'Register & Varieties', year: 2013, question: '"Prescription" belongs to which register?', options: { A: 'Political', B: 'Legal', C: 'Military', D: 'Medical' }, answer: 'D', explanation: 'Prescription is medical register (doctor\'s written order for medicine)' },
  { id: 'eng-2013-43', subject: 'english', topic: 'Register & Varieties', year: 2013, question: 'Pidgin English is an example of', options: { A: 'Foreign language', B: 'Standard English', C: 'Language variety', D: 'Sign language' }, answer: 'C', explanation: 'Pidgin is a simplified language variety used between groups without common language' },
  { id: 'eng-2013-44', subject: 'english', topic: 'Register & Varieties', year: 2013, question: '"The patient presented with acute symptoms" is ___ register', options: { A: 'Political', B: 'Legal', C: 'Literary', D: 'Medical' }, answer: 'D', explanation: '"Patient", "presented", "acute symptoms" are medical terminology' },
  { id: 'eng-2013-45', subject: 'english', topic: 'Register & Varieties', year: 2013, question: 'Formal English is most appropriate for', options: { A: 'Social media posts', B: 'Text messages', C: 'Chatting with friends', D: 'Official letters' }, answer: 'D', explanation: 'Formal English is used in official, professional, and academic contexts' },
];

